// Desired label NAMES from AI
const wantedNames = [
  $node["B-Label Gate"].json.a_label,
  $node["B-Label Gate"].json.b_label
].filter(l => l && l !== "null");

// Grab email metadata to carry through (fixes paired item chain break)
const gmailData = $node["Gmail Poll Inbox"].json;
const fromRaw = gmailData.From || '';
const emailMatch = fromRaw.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1].toLowerCase() : fromRaw.toLowerCase().trim();

const items = $input.all().map(i => i.json);
const nameToId = new Map(items.map(l => [l.name, l.id]));

const wantedIds = wantedNames.map(n => nameToId.get(n)).filter(Boolean);

if (wantedIds.length !== wantedNames.length) {
  const missing = wantedNames.filter(n => !nameToId.get(n));
  throw new Error("Missing Gmail labels: " + missing.join(", "));
}

return [{
  json: {
    messageId: gmailData.id,
    threadId: gmailData.threadId,
    senderEmail: senderEmail,
    senderName: fromRaw,
    subject: gmailData.Subject || '',
    snippet: gmailData.snippet || '',
    a_label: $node["B-Label Gate"].json.a_label || '',
    b_label: $node["B-Label Gate"].json.b_label || null,
    a_confidence: $node["B-Label Gate"].json.a_confidence || 0,
    b_confidence: $node["B-Label Gate"].json.b_confidence || 0,
    labelIds: wantedIds,
    wantedNames
  }
}];

const { messageId, threadId, senderEmail, senderName, subject, snippet, labelIds, a_label, b_label, a_confidence, b_confidence } = $json;

if (!messageId) throw new Error("Missing messageId");
if (!Array.isArray(labelIds) || labelIds.length === 0) throw new Error("Missing labelIds");

return labelIds.map(labelId => ({
  json: { messageId, threadId, senderEmail, senderName, subject, snippet, labelId, a_label, b_label, a_confidence, b_confidence }
}));

const raw = $json.triage?.skip ?? $json.skip ?? false;

const skip_bool =
  raw === true ? true :
  raw === false ? false :
  (typeof raw === "string" ? raw.trim().toLowerCase() === "true" : false);

return [{ json: { ...$json, skip_bool } }];

// Keep the original Gmail trigger item + add parsed AI fields onto it

const aiText = $json.output?.[0]?.content?.[0]?.text;
if (!aiText) throw new Error("No OpenAI text output found at output[0].content[0].text");

let parsed;
try {
  parsed = JSON.parse(aiText);
} catch (e) {
  throw new Error("OpenAI output was not valid JSON. Raw text: " + aiText);
}

// IMPORTANT: merge the parsed AI fields into the incoming item
// so we keep the Gmail fields like id, labels, Subject, From, etc.
return [{
  ...$json,          // original item (from OpenAI node input)
  triage: parsed,    // put AI result under triage (clean namespace)
  ...parsed          // ALSO flatten for convenience (optional)
}];

// ===== SETTINGS =====
const B_LABEL_MIN_CONFIDENCE = 0.80; // B-label confidence threshold

// ===== INPUT =====
const a = $json.a_label ?? $json.triage?.a_label ?? null;
let b = $json.b_label ?? $json.triage?.b_label ?? null;

const aConf = $json.a_confidence ?? $json.triage?.a_confidence ?? 0;
const bConf = $json.b_confidence ?? $json.triage?.b_confidence ?? 0;

// Normalize b_label strings like "null"
if (b === "null") b = null;

// B-label only allowed for Sales/CS
const bAllowed = (a === "TAG-SYS/Sales" || a === "TAG-SYS/CS");

// Gate rule: must pass BOTH a_confidence >= 0.70 AND b_confidence >= 0.80
if (!bAllowed || aConf < 0.70 || bConf < B_LABEL_MIN_CONFIDENCE || !b) {
  b = null;
}

// Extra safety: prefix match
if (b && a === "TAG-SYS/Sales" && !String(b).startsWith("TAG-SYS/Sales/")) b = null;
if (b && a === "TAG-SYS/CS" && !String(b).startsWith("TAG-SYS/CS/")) b = null;

// Write back
const out = { 
  ...$json, 
  a_confidence: aConf,
  b_confidence: bConf,
  b_label: b 
};

if (out.triage && typeof out.triage === "object") {
  out.triage = { 
    ...out.triage, 
    a_confidence: aConf,
    b_confidence: bConf,
    b_label: b 
  };
}

return [{ json: out }];

const enriched = $input.first().json || {};
const meta = $('Switch').first().json || {};

const identity = enriched.identity || {};
const deals = enriched.deals || [];
const dealContext = enriched.deal_context || null;
const order = enriched.order || null;
const financials = enriched.financials || {};
const thread = enriched.thread || {};

let context = '';
if (identity.name) context += 'Contact: ' + identity.name;
if (identity.org_name) context += ' @ ' + identity.org_name;
if (identity.new_contact) context += ' [NEW - not in Pipedrive]';
context += '\n';

if (deals.length > 0) {
  context += '\nActive Pipedrive deals:\n';
  for (const d of deals) {
    context += '- ' + d.title + ' | Stage: ' + d.stage;
    if (d.service_type) context += ' | Service: ' + d.service_type;
    if (d.value) context += ' | Value: $' + d.value;
    if (d.quantity) context += ' | Qty: ' + d.quantity;
    if (d.deadline) context += ' | Deadline: ' + d.deadline;
    if (d.item_of_interest) context += ' | Item: ' + d.item_of_interest;
    context += '\n';
  }
}

if (dealContext && dealContext.content) {
  context += '\n=== DEAL CONTEXT (compiled from all deal notes & transcripts) ===\n';
  context += dealContext.content;
  context += '\n=== END DEAL CONTEXT ===\n';
}

if (order) {
  context += '\nMonday order status: ' + (order.human_readable || order.found_on_board || 'unknown') + '\n';
}

if (financials.outstanding_balance > 0) {
  context += '\nOutstanding balance: $' + financials.outstanding_balance;
  if (financials.open_invoices?.length > 0) {
    context += ' | Open invoices: ' + financials.open_invoices.map(inv => '#' + (inv.doc_number || '?') + ' ($' + inv.amount + ')').join(', ');
  }
  context += '\n';
}

if (thread.summary) {
  context += '\nThread summary (' + (thread.message_count || '?') + ' messages):\n' + thread.summary + '\n';
}

const systemPrompt = 'You are a sales email sub-classifier for Dads Printing (custom apparel). You have FULL deal context from Pipedrive including compiled deal notes and call transcripts, Monday order status, QuickBooks financials, and the email thread summary.\n\nClassify into exactly ONE B-label. Respond ONLY with valid JSON, no markdown.\n\nOPTIONS:\n- TAG-SYS/Sales/QUOTE: Customer gave enough to actually BUILD a quote. ALL THREE must be present (from the email, thread, OR deal context combined):\n  1. Product type is clear (e.g. t-shirts, hoodies, jerseys, patches)\n  2. Quantity or range is known (e.g. 50, 15-20, ~100)\n  3. Print/decoration configuration is known — at least ONE of: artwork file attached or referenced, print method specified (screenprint, DTG, embroidery, sublimation), number of colors/print locations mentioned, or prior deal context contains these specs\n\n  If #3 is missing — even if product + quantity are clear — this is NEEDS-INFO, not QUOTE.\n  Example: "15-20 red shirts women\'s neck" = NEEDS-INFO (no artwork, no print method, no color count for print)\n  Example: "50 black tees, 1-color front print, logo attached" = QUOTE\n  Example: "same order as last time, 60 hoodies" = QUOTE (prior specs exist)\n\n- TAG-SYS/Sales/NEEDS-INFO: Not enough to quote. Product type unclear, OR no quantity, OR print/decoration configuration unknown (no artwork info, no print method, no color/location details anywhere in email + deal context + thread).\n- TAG-SYS/Sales/INVOICE: Deal at Quote Sent or Won stage, customer is approving/ready to pay.\n- TAG-SYS/Sales/LOST: Customer explicitly declined or went elsewhere.\n- null: Uncertain. General sales correspondence.\n\nCRITICAL RULES:\n- QUOTE requires ALL THREE: product + quantity + print configuration. Missing ANY ONE = NEEDS-INFO.\n- "Product + quantity only" with NO artwork/print details = NEEDS-INFO. This is the most common misclassification — do NOT mark as QUOTE.\n- Garment color (e.g. "red shirts") is NOT the same as print configuration. Garment color tells us the blank, not the decoration.\n- If DEAL CONTEXT contains product + quantity + artwork/specs from prior conversations = QUOTE\n- If thread summary + deal context together provide enough detail to price = QUOTE\n- Customer says reorder/same as last time = QUOTE (prior specs exist)\n- Brand new inquiry with just product + quantity but zero print/artwork detail = NEEDS-INFO\n- Deal at Quote Sent + approval language = INVOICE\n- When in doubt between QUOTE and NEEDS-INFO = NEEDS-INFO (safer to ask than to delay)\n- null only for general correspondence that is neither quotable nor missing info\n\nFORMAT: {"b_label": "TAG-SYS/Sales/QUOTE", "b_confidence": 0.92, "reason": "short explanation"}';

const userPrompt = 'DEAL CONTEXT:\n' + context + '\nEMAIL:\nSubject: ' + (meta.subject || '') + '\nFrom: ' + (meta.senderEmail || '') + '\nSnippet: ' + (meta.snippet || '') + '\n\nClassify now.';

const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 150,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }]
};

return [{ json: { ...meta, _enriched: enriched, _blabel_request: requestBody } }];

const aiResp = $input.first().json;
const prev = $('Build Enriched B-Label Prompt').first().json;
const B_LABEL_MIN = 0.75;

let b_label = null;
let b_confidence = 0;
let reason = 'enrichment_failed';
let next_action = null;

try {
  const text = (aiResp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
  const clean = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);

  next_action = parsed.next_action || null;

  if (parsed.b_label && parsed.b_label !== 'null') {
    b_confidence = parsed.b_confidence || 0;
    reason = parsed.reason || '';

    if (b_confidence >= B_LABEL_MIN && String(parsed.b_label).startsWith('TAG-SYS/Sales/')) {
      b_label = parsed.b_label;
    }
  }
} catch(e) {
  reason = 'parse_error: ' + e.message;
}

const { _enriched, _blabel_request, ...itemData } = prev;
return [{ json: {
  ...itemData,
  b_label: b_label,
  b_confidence: b_confidence,
  _enriched_reason: reason,
  _enriched_next_action: next_action
} }];

// Phase 1: Hard skip form submissions — forms are intake-only, never reply
const subject = ($json.Subject || '').toLowerCase();
const from = ($json.From || '').toLowerCase();

// Form submission emails from Elementor/WP contact forms
if (subject.includes('form submission') && from.includes('info@dadsprinting.com')) {
  return []; // Empty = workflow stops here, no downstream execution
}

// "New message" or "New Form" notifications from the website
if ((subject.includes('new message - dads printing') || subject.includes('new form')) 
    && (from.includes('info@dadsprinting.com') || from.includes('noreply') || from.includes('wordpress'))) {
  return []; // Hard skip
}

// Not a form — pass through unchanged
return [$input.first()];

// ===== SUPPRESSION GATE =====
const item = $('Apply Enriched B-Label').first().json;
const enriched = $('Enrich Sales Context').first().json || {};
const deals = enriched.deals || [];
const firstDeal = deals[0] || {};
const dealContext = enriched.deal_context || {};
const order = enriched.order || {};
const next_action = item._enriched_next_action || null;

const cooldownRows = $input.all().map(i => i.json);
let draft_cooldown = false;
let last_draft_source = null;
let last_draft_age_min = null;
const now = new Date();
const COOLDOWN_MINUTES = 60;

for (const row of cooldownRows) {
  if (!row.timestamp || !row.b_label) continue;
  const rowTime = new Date(row.timestamp);
  if (isNaN(rowTime.getTime())) continue;
  const ageMin = Math.round((now - rowTime) / 60000);
  if (ageMin <= COOLDOWN_MINUTES && row.b_label && row.b_label !== 'null') {
    draft_cooldown = true;
    last_draft_source = row.b_label;
    last_draft_age_min = ageMin;
    break;
  }
}

let draft_allowed = true;
let suppress_reason = '';

if (draft_cooldown) {
  draft_allowed = false;
  suppress_reason = 'Draft cooldown: ' + last_draft_source + ' drafted ' + last_draft_age_min + 'min ago';
}

if (draft_allowed && dealContext.di_note_complete && firstDeal.stage_id >= 15) {
  draft_allowed = false;
  suppress_reason = 'DQM owns this deal (Stage ' + firstDeal.stage_id + ' + DI complete)';
}

if (draft_allowed && order.active_order) {
  draft_allowed = false;
  suppress_reason = 'Active order on ' + (order.active_board || 'Monday');
}

if (draft_allowed && firstDeal.stage_id === 16) {
  draft_allowed = false;
  suppress_reason = 'Deal already at Invoice Paid';
}

if (draft_allowed && next_action === 'queue_quote' && firstDeal.stage_id >= 8 && dealContext.di_note_complete) {
  draft_allowed = false;
  suppress_reason = 'queue_quote suppressed - DQM pipeline active';
}

const lifecycle = enriched.lifecycle_stage || null;
if (draft_allowed && lifecycle === 'in_production' && order.active_order) {
  draft_allowed = false;
  suppress_reason = 'In production lifecycle with active Monday order';
}
if (draft_allowed && lifecycle === 'delivered') {
  draft_allowed = false;
  suppress_reason = 'Thread lifecycle: delivered';
}

if (!draft_allowed) {
  return [{ json: { ...item, b_label: null, draft_allowed, suppress_reason, draft_cooldown, last_draft_source, last_draft_age_min } }];
}

return [{ json: { ...item, draft_allowed: true, suppress_reason: '', draft_cooldown: false, last_draft_source: null, last_draft_age_min: null } }];
